// _chain_sizeSliceInt32 returns the length of the encoding of the elements of
// x, a []int32.
func _chain_sizeSliceInt32(x []int32) int {
	n := 0
	for k := range x {
		n += wire.SizeUvarint(wire.Zigzag(int64(x[k])))
	}
	return n
}

// _chain_sizePtrString returns the length of the encoding of x, a *string: its
// presence byte and the value that it points at.
func _chain_sizePtrString(x *string) int {
	if x == nil {
		return 1
	}
	return 1 + wire.SizeBytes(len(*x))
}

// _chain_putPtrString writes the encoding of x, a *string, into the end of buf,
// which has room for it, and returns its length.
func _chain_putPtrString(buf []byte, x *string) int {
	i := len(buf)
	if x != nil {
		i = wire.PutRaw(buf, i, *x)
		i = wire.PutUvarint(buf, i, uint64(len(*x)))
	}
	i = wire.PutBool(buf, i, x != nil)
	return len(buf) - i
}

// _chain_putSliceInt32 writes the encoding of x, a []int32, into the end of
// buf, which has room for it, and returns its length.
func _chain_putSliceInt32(buf []byte, x []int32) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		i = wire.PutUvarint(buf, i, wire.Zigzag(int64(x[k])))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _chain_readSliceInt32 appends the elements that data encodes, a []int32
// without its length, to *dst. data starts at offset off of slab, and the
// decode enters depth levels below the value at most. loc and num locate the
// field in errors.
func _chain_readSliceInt32(dst *[]int32, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([]int32, 0, wire.CountVarints(data))
	}
	for i := 0; i < len(data); {
		x = append(x, 0)
		last := len(x) - 1
		u, n := wire.Uvarint(data[i:])
		if n <= 0 {
			return wire.ReadError(n, loc, num, off+i)
		}
		s := wire.Unzigzag(u)
		if s != int64(int32(s)) {
			return wire.RangeError(s, "int32", loc, num, off+i)
		}
		x[last] = int32(s)
		i += n
	}
	*dst = x
	return nil
}

// _chain_readPtrString decodes the *string at the start of data into *dst and
// returns the length of its encoding: nil for the presence byte 0, and for the
// presence byte 1 the value that follows, into the value that *dst points at or
// into a new one. data starts at offset off of slab, and the decode enters
// depth levels below the value at most. loc and num locate the field in errors.
func _chain_readPtrString(dst **string, data []byte, slab string, off, depth int, loc string, num int) (int, error) {
	if depth < 0 {
		return 0, wire.DepthError(loc, num, off)
	}
	present, err := wire.Presence(data, loc, num, off)
	if err != nil {
		return 0, err
	}
	if !present {
		*dst = nil
		return 1, nil
	}
	x := *dst
	if x == nil {
		x = new(string)
		*dst = x
	}
	i := 1
	l, n := wire.Uvarint(data[i:])
	if n <= 0 || uint64(len(data)-i-n) < l {
		return 0, wire.ReadError(n, loc, num, off+i)
	}
	i += n
	*x = slab[off+i : off+i+int(l)]
	i += int(l)
	return i, nil
}

